package os.kei.hyper.home.xposed

import os.kei.hyper.home.iconpack.NativeDayNightIcon
import os.kei.hyper.home.iconpack.NativePaletteIcon
import os.kei.hyper.home.iconpack.NativeColorOsDynamicIcon

/** Compares generated bytes without parsing or admitting supplied MAML programs. */
internal object GeneratedNativeIconValidator {
  private const val PNG_LIMIT = 4L * 1024 * 1024
  private val clockNames = listOf(
    "clock_day_bg.png", "clock_day_hour_rectangle.png", "clock_day_minute_rectangle.png",
    "night_clock_day_bg.png", "night_clock_day_hour_rectangle.png", "night_clock_day_minute_rectangle.png",
  )

  fun validate(name: String, paths: Set<String>, read: (String, Long) -> ByteArray) {
    val root = "fancy_icons/$name/"
    val actualPaths = paths.filterTo(HashSet()) { it.startsWith(root) }
    val cache = HashMap<String, ByteArray>()
    fun bytes(path: String) = cache.getOrPut(path) {
      read(path, if (path == "${root}manifest.xml") 64L * 1024 else PNG_LIMIT)
    }
    val light = bytes("res/drawable-xxhdpi/$name.png")
    val dark = bytes("nightmode/res/drawable-xxhdpi/$name.png")
    fun matches(canonical: Map<String, ByteArray>): Boolean {
      val expected = canonical.filterKeys { it.startsWith(root) }
      return actualPaths == expected.keys && expected.all { (path, value) ->
        bytes(path).contentEquals(value)
      }
    }
    if ("${root}mask.png" in actualPaths) {
      require(matches(NativePaletteIcon.entries(name, light, dark,
        bytes("${root}mask.png"), bytes("${root}bg.png")))) {
        "Incomplete or noncanonical generated palette icon: $name"
      }
      return
    }
    if (matches(NativeDayNightIcon.entries(name, light, dark))) return

    val kind = if (clockNames.any { "$root$it" in actualPaths }) NativeColorOsDynamicIcon.Kind.CLOCK
      else NativeColorOsDynamicIcon.Kind.CALENDAR
    // Handoff uses the source backgrounds as its normal fallback pair, without optional snapshots.
    val assets = linkedMapOf("day.png" to light, "night.png" to dark)
    if (kind == NativeColorOsDynamicIcon.Kind.CLOCK) {
      for (leaf in clockNames) assets[leaf] = bytes("$root$leaf")
    }
    for (fixedDark in listOf(null, false, true)) for (dim in listOf(false, true)) {
      if (matches(NativeColorOsDynamicIcon.entries(name, kind, assets, fixedDark, dim))) return
    }
    error("Incomplete or noncanonical generated icon resources: $name")
  }
}
